questionvariables.text:
ordergreat(i,j,k); texput(i,"\\mathbf{i}"); texput(j,"\\mathbf{j}"); texput(k,"\\mathbf{k}");
validate_ijk(ex) := if listp(ex) or matrixp(ex) or listofvars(ex) = [] then "Write the vector with i, j and k, for example 3*i-2*k." else if every(lambda([vv], member(vv, [i,j,k])), listofvars(ex)) then "" else "Use only the letters i, j and k.";
cv3(v) := matrix([v[1]],[v[2]],[v[3]]);
/* Design: find the mistake in a vector calculation. er 2: step 2 scales only the first component of a; er 3: step 3 adds q to each component of b; er 4: step 4 treats -(-x) as -x at the first negative component of b. Later steps carry the error forward. Source: original. */
alist: [[[5,6,4],[-2,-5,-4],4,3],[[5,-5,2],[-2,-1,-3],2,3],[[5,5,-6],[5,-4,4],3,4],[[5,2,3],[4,1,-3],4,3],[[2,-3,-5],[-2,5,5],2,3],[[-3,-6,4],[5,-4,-3],2,3],[[-4,-3,-5],[3,-2,-4],3,2],[[5,-5,-2],[-3,-2,1],3,2],[[-2,4,-4],[5,-3,2],3,2],[[1,2,4],[-1,-1,-3],2,3]];
ix: 1+rand(10); er: rand([2,3,4]);
A: alist[ix][1]; B: alist[ix][2]; p: alist[ix][3]; q: alist[ix][4];
ta: A[1]*i+A[2]*j+A[3]*k; tb: B[1]*i+B[2]*j+B[3]*k;
mneg: first(sublist_indices(B, lambda([t], is(t < 0))));
s2: if er = 2 then [p*A[1], A[2], A[3]] else p*A;
s3: if er = 3 then B+q else q*B;
s4: makelist(if er = 4 and m = mneg then s2[m]+s3[m] else s2[m]-s3[m], m, 1, 3);
sh: s4[1]*i+s4[2]*j+s4[3]*k;
okl: p*A-q*B; okv: okl[1]*i+okl[2]*j+okl[3]*k;
rev: -okv; okw: okv+i; lst: [1,2,3];
c2: p*A; c3: q*B;
opts: [["s1",false,"Step 1"],["s2",is(er=2),"Step 2"],["s3",is(er=3),"Step 3"],["s4",is(er=4),"Step 4"],["s5",false,"Step 5"]];
ta1: first(mcq_correct(opts));
gws: if er = 2 then "s3" else "s2";
